insert into public.questions
  (section, topic, difficulty, body, options, correct_idx, explanation, time_limit_s, template, variant, code)
values
  ('coding', 'Operators', 1, 'What does this code print?', array['19 1', '19 2', '19 0', '0 19'], 2, 'With whole numbers, / drops the fraction and % gives the remainder: 57 = 19 × 3 + 0. It prints 19 0.', 40, 'coding-div-mod', 'c1521749f75bedf5', '{"c":"int a = 57;\nint b = 3;\nprintf(\"%d \", a / b);\nprintf(\"%d \", a % b);","cpp":"int a = 57;\nint b = 3;\ncout << (a / b) << \" \";\ncout << (a % b) << \" \";","java":"int a = 57;\nint b = 3;\nSystem.out.print((a / b) + \" \");\nSystem.out.print((a % b) + \" \");","python":"a = 57\nb = 3\nprint(a // b, end=\" \")\nprint(a % b, end=\" \")","pseudo":"// \"/\" is integer division: 7 / 2 = 3\n\nInteger a = 57\nInteger b = 3\nprint a / b\nprint a mod b"}'::jsonb),
