  ('coding', 'Bitwise', 2, 'What does this code print?', array['15 1', '15 15', '15 0', '0 15'], 2, 'In binary a = 111 and b = 1000. & keeps bits set in both, | keeps bits set in either, ^ keeps bits set in exactly one. It prints 15 0.', 50, 'coding-bitwise', '7bca5282ab29658f', '{"c":"int a = 7;\nint b = 8;\nprintf(\"%d \", a ^ b);\nprintf(\"%d \", a & b);","cpp":"int a = 7;\nint b = 8;\ncout << (a ^ b) << \" \";\ncout << (a & b) << \" \";","java":"int a = 7;\nint b = 8;\nSystem.out.print((a ^ b) + \" \");\nSystem.out.print((a & b) + \" \");","python":"a = 7\nb = 8\nprint(a ^ b, end=\" \")\nprint(a & b, end=\" \")","pseudo":"Integer a = 7\nInteger b = 8\nprint a ^ b\nprint a & b"}'::jsonb),
