  ('coding', 'Recursion', 2, 'What does this code print?', array['17', '16', '4', '2'], 1, 'Each call takes the last digit (n % 10) and recurses on the rest (n / 10), so f adds the digits of 5812: 16.', 50, 'coding-digits-rec', '75dd6e8dfd6d190c', '{"c":"int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\nprintf(\"%d \", f(5812));","cpp":"int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\ncout << f(5812) << \" \";","java":"static int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\nSystem.out.print(f(5812) + \" \");","python":"def f(n):\n    if n == 0:\n        return 0\n    return n % 10 + f(n // 10)\n\nprint(f(5812), end=\" \")","pseudo":"// \"/\" is integer division: 7 / 2 = 3\n\nfunction f(n)\n  if (n == 0)\n    return 0\n  end if\n  return n mod 10 + f(n / 10)\nend function\n\nprint f(5812)"}'::jsonb)
